// === SELLER PORTAL AUTH GATE ===
// Insert at TOP of penjual.html <script> block, before any POS logic.
const AUTH_KEY = 'kantin_penjual_auth';
const VALID_CREDENTIALS = {
  username: 'admin',
  password: 'boash123'
};

function isSellerAuthenticated() {
  return sessionStorage.getItem(AUTH_KEY) === 'authenticated';
}

function showLoginModal() {
  const overlay = document.getElementById('login-overlay');
  if (overlay) overlay.classList.remove('hidden');
}

function hideLoginModal() {
  const overlay = document.getElementById('login-overlay');
  if (overlay) overlay.classList.add('hidden');
}

function handleLogin(e) {
  e.preventDefault();
  const user = document.getElementById('login-user').value.trim();
  const pass = document.getElementById('login-pass').value;
  const errorEl = document.getElementById('login-error');

  if (user === VALID_CREDENTIALS.username && pass === VALID_CREDENTIALS.password) {
    sessionStorage.setItem(AUTH_KEY, 'authenticated');
    hideLoginModal();
    initPOS(); // Start POS polling only after auth
  } else {
    errorEl.textContent = 'Username atau password salah.';
    errorEl.classList.remove('hidden');
  }
}

function handleLogout() {
  sessionStorage.removeItem(AUTH_KEY);
  location.reload();
}

// Gate: check auth on DOMContentLoaded
function initSellerPortal() {
  if (isSellerAuthenticated()) {
    hideLoginModal();
    initPOS();
  } else {
    showLoginModal();
  }
}
